        owner_of("plugin.wasm").contains("plugin-crate"),
        "{}",
        owner_of("plugin.wasm")
    );
    assert!(
        owner_of("core-linux.tar.gz").contains("core-crate"),
        "{}",
        owner_of("core-linux.tar.gz")
    );
}

