import json, subprocess, collections

def run(args):
    r = subprocess.run(["entire", *args], capture_output=True, text=True)
    return json.loads(r.stdout)

sev = collections.Counter()
status = collections.Counter()
rows = []
seen = 0
for n in range(120, 240):
    try:
        f = run(["trail", "finding", "list", str(n), "--json"])
    except Exception:
        continue
    fs = f.get("findings", [])
    if not fs:
        continue
    seen += 1
    for x in fs:
        sev[x["severity"]] += 1
        status[x["status"]] += 1
        loc = x.get("location") or {}
        rows.append((n, x["severity"], x["status"], (x["body"] or "")[:140].replace("\n", " "), loc.get("filePath", "")))
print("trails with findings:", seen)
print("severity", dict(sev))
print("status", dict(status))
print("total", len(rows))
for r in sorted(rows, key=lambda r: ({"high": 0, "medium": 1, "low": 2}.get(r[1], 3), r[0])):
    print("|".join(str(c) for c in r))

