/// escaped; otherwise a title such as ``Fix `<T>` `` would lose its `<T>` as an unknown tag.
fn summary_html(text: &str) -> String {
    fn escape(text: &str) -> String {
        text.replace('&', "&amp;").replace('<', "&lt;").replace('>', "&gt;")
    }
    let mut out = String::new();
    let mut rest = text;
