        Ok(Some(plan)) => plan,
        Ok(None) => {
            return PublishOutlook::Planned {
                releases: Vec::new(),
                notes: Vec::new(),
            }
        }
        Err(error) => {
            let code = miette::Diagnostic::code(&error).map(|code| code.to_string());
            return PublishOutlook::Blocked {
                code,
                message: error.to_string(),
